<?php require __DIR__.'/../includes/bootstrap.php';require_admin();$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';try{if($action==='delete'){$id=(int)$_POST['id'];$s=$pdo->prepare('DELETE FROM products WHERE id=?');$s->execute([$id]);}else{$id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');$price=max(0,(float)($_POST['price']??0));$category=(int)($_POST['category_id']??0)?:null;$desc=trim($_POST['description']??'');$active=isset($_POST['active'])?1:0;if($name==='')throw new RuntimeException('اسم المنتج مطلوب.');$image=upload_image($_FILES['image']??[]);if($id){if($image){$s=$pdo->prepare('UPDATE products SET name=?,price=?,category_id=?,description=?,active=?,image=? WHERE id=?');$s->execute([$name,$price,$category,$desc,$active,$image,$id]);}else{$s=$pdo->prepare('UPDATE products SET name=?,price=?,category_id=?,description=?,active=? WHERE id=?');$s->execute([$name,$price,$category,$desc,$active,$id]);}}else{$s=$pdo->prepare('INSERT INTO products(name,price,category_id,description,active,image) VALUES(?,?,?,?,?,?)');$s->execute([$name,$price,$category,$desc,$active,$image]);}}header('Location: products.php');exit;}catch(Throwable $e){$error=$e->getMessage();}}
$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM products WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}$page_title='إدارة المنتجات';require __DIR__.'/../includes/header.php';?><main class="container"><h1 class="gold">إدارة المنتجات</h1><?php require __DIR__.'/nav.php';?><div class="panel"><h2><?= $edit?'تعديل المنتج':'إضافة منتج جديد'?></h2><?php if($error):?><div class="alert"><?=e($error)?></div><?php endif;?><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)($edit['id']??0)?>"><div class="form-grid"><div class="field"><label>اسم المنتج *</label><input name="name" required value="<?=e($edit['name']??'')?>"></div><div class="field"><label>السعر</label><input name="price" type="number" step="0.01" min="0" value="<?=e((string)($edit['price']??''))?>"></div><div class="field"><label>القسم</label><select name="category_id"><option value="">بدون قسم</option><?php foreach($pdo->query('SELECT * FROM categories ORDER BY name') as $c):?><option value="<?=$c['id']?>" <?=($edit['category_id']??'')==$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></div><div class="field"><label>صورة المنتج (حتى 4MB)</label><input type="file" name="image" accept="image/jpeg,image/png,image/webp"></div></div><div class="field"><label>الوصف</label><textarea name="description"><?=e($edit['description']??'')?></textarea></div><label><input style="width:auto" type="checkbox" name="active" <?=(!$edit||($edit['active']??0))?'checked':''?>> إظهار المنتج في المتجر</label><button class="btn">حفظ المنتج</button><?php if($edit):?> <a class="btn secondary" href="products.php">إلغاء</a><?php endif;?></form></div><div class="panel table-wrap"><h2>المنتجات الحالية</h2><table><tr><th>المنتج</th><th>السعر</th><th>الحالة</th><th>إجراء</th></tr><?php foreach($pdo->query('SELECT * FROM products ORDER BY id DESC') as $p):?><tr><td><?=e($p['name'])?></td><td><?=money($p['price'])?></td><td><?=$p['active']?'ظاهر':'مخفي'?></td><td><a class="gold" href="?edit=<?=$p['id']?>">تعديل</a> <form class="inline" method="post" onsubmit="return confirm('حذف المنتج؟')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$p['id']?>"><button class="btn secondary danger" name="action" value="delete">حذف</button></form></td></tr><?php endforeach;?></table></div></main><?php require __DIR__.'/../includes/footer.php';?>
